<?php
declare(strict_types=1);
require_once __DIR__ . '/../functions/helpers.php';
require_role('admin');
$status=clean_text((string)($_GET['status']??''));$allowed=['pending','processing','shipped','completed','cancelled'];
$sql="SELECT o.id,o.total_amount,o.status,o.created_at,u.name,u.email FROM orders o INNER JOIN users u ON u.id=o.user_id";$params=[];if(in_array($status,$allowed,true)){$sql.=' WHERE o.status=?';$params[]=$status;}$sql.=' ORDER BY o.created_at DESC';$stmt=db()->prepare($sql);$stmt->execute($params);$orders=$stmt->fetchAll();$flash=get_flash();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Orders | Gonzaga's Apparel</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/admin.css"></head><body class="admin-page"><header class="admin-header"><a href="../index.php"><img src="../assets/images/logo-placeholder.svg" alt="Gonzaga's Apparel"></a><div><a href="dashboard.php">DASHBOARD</a><form action="../logout.php" method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><button type="submit">LOG OUT</button></form></div></header><main class="admin-shell"><div class="section-kicker">ORDER MANAGEMENT <span></span></div><h1>ORDERS</h1><?php if($flash):?><div class="alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif;?><form class="admin-filter" method="get"><label>FILTER BY STATUS<select name="status"><option value="">All statuses</option><?php foreach($allowed as $s):?><option value="<?=e($s)?>" <?=$status===$s?'selected':''?>><?=e(ucfirst($s))?></option><?php endforeach;?></select></label><button class="button button--filled" type="submit">FILTER</button></form><section class="admin-card"><div class="table-wrap"><table><thead><tr><th>ORDER</th><th>CUSTOMER</th><th>DATE</th><th>TOTAL</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><?php foreach($orders as $order):?><tr><td><a class="table-link" href="order.php?id=<?=intval($order['id'])?>">#<?=intval($order['id'])?></a></td><td><strong><?=e($order['name'])?></strong><small><?=e($order['email'])?></small></td><td><?=e($order['created_at'])?></td><td><?=money((float)$order['total_amount'])?></td><td><?=e(strtoupper($order['status']))?></td><td><a class="button button--outline" href="order.php?id=<?=intval($order['id'])?>">VIEW</a></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>
